enum OperationType {
  CREATE = "create",
  UPDATE = "update",
  DELETE = "delete",
  LIST = "list",
  GET = "get",
  WRITE = "write",
}

interface FirestoreErrorInfo {
  error: string;
  operationType: OperationType;
  path: string | null;
  authInfo: {
    userId?: string | null;
    email?: string | null;
    emailVerified?: boolean | null;
    isAnonymous?: boolean | null;
    tenantId?: string | null;
    providerInfo?: {
      providerId?: string | null;
      email?: string | null;
    }[];
  };
}

function handleFirestoreError(
  error: unknown,
  operationType: OperationType,
  path: string | null,
) {
  const errInfo: FirestoreErrorInfo = {
    error: error instanceof Error ? error.message : String(error),
    authInfo: {
      userId: auth.currentUser?.uid,
      email: auth.currentUser?.email,
      emailVerified: auth.currentUser?.emailVerified,
      isAnonymous: auth.currentUser?.isAnonymous,
      tenantId: auth.currentUser?.tenantId,
      providerInfo:
        auth.currentUser?.providerData?.map((provider) => ({
          providerId: provider.providerId,
          email: provider.email,
        })) || [],
    },
    operationType,
    path,
  };

  const lowerErr = errInfo.error.toLowerCase();

  const isPermissionError =
    lowerErr.includes("permission") || lowerErr.includes("insufficient");

  if (isPermissionError) {
    console.warn(`Firestore Permission (${operationType} on ${path}): ${errInfo.error}`);
    return;
  }

  console.error("Firestore Error: ", JSON.stringify(errInfo));
  throw new Error(JSON.stringify(errInfo));
}

export function getFriendlyError(err: any): string {
  let msg = err.message || String(err);
  try {
    const parsed = JSON.parse(msg);
    if (parsed.error) msg = parsed.error;
  } catch (e) {}

  if (msg.includes("Missing or insufficient permissions")) {
    return "మీకు ఈ యాక్షన్‌ని చేయడానికి పర్మిషన్ లేదు / You don't have permission to perform this action.";
  }
  if (
    msg.includes("offline") ||
    msg.includes("network-request-failed") ||
    msg.includes("Failed to get document because the client is offline")
  ) {
    return "ఇంటర్నెట్ కనెక్షన్ లేదు. దయచేసి నెట్‌వర్క్ చెక్ చేయండి / No internet connection. Please check your network.";
  }
  if (msg.includes("Quota exceeded")) {
    return "సిస్టమ్ పరిమితి దాటింది. దయచేసి రేపు మళ్ళీ ప్రయత్నించండి / Quota exceeded. Please try again tomorrow.";
  }
  if (
    msg.includes("invalid-credential") ||
    msg.includes("user-not-found") ||
    msg.includes("wrong-password")
  ) {
    return "లాగిన్ వివరాలు తప్పు. దయచేసి సరియైన లాగిన్ వివరాలు ప్రయత్నించండి / Invalid credentials. Please try again.";
  }
  if (
    msg.includes("popup-closed-by-user") ||
    msg.includes("cancelled-popup-request")
  ) {
    return "లాగిన్ విండో మూసివేయబడింది. దయచేసి మళ్ళీ ప్రయత్నించండి / The login popup was closed before completion.";
  }
  if (msg.includes("unauthorized-domain")) {
    return "ఈ డొమైన్ Firebase Authentication లో ఇంకా అనుమతించబడలేదు. Firebase Console > Authentication > Settings > Authorized domains లో ప్రస్తుత డొమైన్‌ను యాడ్ చేయండి.";
  }

  return msg;
}

export async function sendCommentNotifications(
  postId: string,
  commentText: string,
  authorUid: string,
  authorName: string,
) {
  try {
    const time = Date.now();

    // Global Notification for Comment
    await addDoc(collection(db, "notifications"), {
      uid: "all",
      title: "కొత్త కామెంట్ (New Comment)",
      message: `${authorName} వారు ఒక పోస్ట్‌ పై కామెంట్ చేశారు.`,
      type: "comment",
      read: false,
      time: time,
      postId: postId,
      senderUid: authorUid,
    });

    const mentionRegex = /@([a-zA-Z0-9_]+)/g;
    const mentions = [...commentText.matchAll(mentionRegex)].map((m) =>
      m[1].toLowerCase(),
    );
    const uniqueMentions = [...new Set(mentions)];

    for (const username of uniqueMentions) {
      try {
        const userDoc = await getDoc(doc(db, "usernames", username));
        if (userDoc.exists()) {
          const targetUid = userDoc.data().uid;
          if (targetUid && targetUid !== authorUid) {
            await addDoc(collection(db, "notifications"), {
              uid: targetUid,
              title: "కొత్త మెన్షన్ (New Mention)",
              message: `${authorName} మిమ్మల్ని ఒక కామెంట్‌లో మెన్షన్ చేశారు.`,
              type: "mention",
              read: false,
              time: time,
            });
          }
        }
      } catch (err) {
        console.error(err);
      }
    }

    // Send a single grouped notification to all users
    const q = query(
      collection(db, "notifications"),
      where("uid", "==", "all"),
      where("type", "==", "comment"),
      where("postId", "==", postId),
      limit(1)
    );
    const snap = await getDocs(q);
    if (!snap.empty) {
      await updateDoc(snap.docs[0].ref, {
        message: `${authorName} వారు మరియు ఇతరులు ఒక పోస్టులో కొత్త కామెంట్లు చేశారు.`,
        time: time,
        read: false
      });
    } else {
      await addDoc(collection(db, "notifications"), {
        uid: "all",
        title: "కొత్త కామెంట్ (New Comment)",
        message: `${authorName} వారు ఒక పోస్టులో కొత్త కామెంట్ చేశారు.`,
        type: "comment",
        read: false,
        time: time,
        postId: postId
      });
    }

    // Single admin alert
    await addDoc(collection(db, "notifications"), {
      uid: "all",
      title: "కొత్త కామెంట్ (New Comment)",
      message: `${authorName} వారు ఒక పోస్ట్‌పై కామెంట్ చేశారు.`,
      type: "admin_alert",
      read: false,
      time: time,
      postId: postId
    }).catch(()=>console.error("Failed to notify admin"));

  } catch (err) {
    console.error("Error sending notifications", err);
  }
}

export async function sendLikeNotification(
  postId: string,
  commentId: string,
  commentText: string,
  commentAuthorUid: string,
  commentAuthorName: string,
  likerUid: string,
  likerName: string,
) {
  try {
    const time = Date.now();

    // Global Notification
    await addDoc(collection(db, "notifications"), {
      uid: "all",
      title: "కామెంట్ లైక్ చేయబడింది (Comment Liked)",
      message: `${likerName} వారు ఒక కామెంట్‌ను ఇష్టపడ్డారు (లైక్ చేశారు).`,
      type: "comment_like",
      read: false,
      time: time,
      postId: postId,
      senderUid: likerUid,
    });

    // 1st Person: Notify the comment author if the liker is not the comment author themself
    if (commentAuthorUid && commentAuthorUid !== likerUid) {
      await addDoc(collection(db, "notifications"), {
        uid: commentAuthorUid,
        title: "మీ కామెంట్ లైక్ చేయబడింది (Comment Liked)",
        message: `${likerName} E-Vedhika సైట్‌లో మీ కామెంట్‌ను ఇష్టపడ్డారు (లైక్ చేశారు). పోస్ట్‌ను చూడటానికి ఇక్కడ క్లిక్ చేయండి.`,
        type: "comment_like",
        read: false,
        time: time,
        postId: postId,
      });
    }

    // 2nd group: Notify ALL other users who commented on this post (except the liker and the comment author)
    const commentsSnap = await getDocs(
      collection(db, "posts", postId, "comments"),
    );
    const uids = new Set<string>();
    commentsSnap.forEach((d) => {
      const data = d.data();
      if (data.uid) uids.add(data.uid);
    });

    uids.delete(likerUid);
    uids.delete(commentAuthorUid);

    for (const targetUid of Array.from(uids)) {
      try {
        await addDoc(collection(db, "notifications"), {
          uid: targetUid,
          title: "కామెంట్‌పై కొత్త స్పందన (Reaction on Post)",
          message: `${likerName} మీరు పాల్గొన్న ఈ-వేదిక పోస్ట్‌లోని ఒక కామెంట్‌ను లైక్ చేశారు.`,
          type: "comment_like",
          read: false,
          time: time,
          postId: postId,
        });
      } catch (err) {
        console.error(err);
      }
    }
  } catch (err) {
    console.error("Error sending like notification", err);
  }
}

const logUserActivity = async (actionDesc: string, details?: any) => {
  try {
    const userDisplay =
      auth.currentUser?.email ||
      auth.currentUser?.displayName ||
      auth.currentUser?.uid ||
      "Anonymous Visitor";
    await addDoc(collection(db, "security_logs"), {
      admin: userDisplay,
      uid: auth.currentUser?.uid || "anonymous",
      action: actionDesc,
      details: details || null,
      time: Date.now(),
      userAgent: navigator.userAgent,
    });
  } catch (e) {
    console.error("Logging error:", e);
  }
};

export function requireLoginAlert(userObj?: any): boolean {
  const account = userObj || auth.currentUser;
  if (!account || account.isAnonymous) {
    Swal.fire({
      text: "లాగిన్ అయ్యాక మీకు యాక్సెస్ ఉంటుంది",
      icon: "info",
      confirmButtonText: "సరే (OK)",
      confirmButtonColor: "#0d3b66",
    });
    return true;
  }
  return false;
}

function formatDistanceToNow(timestamp: number): string {
  const diff = Date.now() - timestamp;
  const seconds = Math.floor(diff / 1000);
  const minutes = Math.floor(seconds / 60);
  const hours = Math.floor(minutes / 60);
  const days = Math.floor(hours / 24);

  if (days > 0) return `${days}d`;
  if (hours > 0) return `${hours}h`;
  if (minutes > 0) return `${minutes}m`;
  return `${seconds}s`;
}

